module.exports = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>3DP LCD settings</title>\n<style>\n:root {\n--bg: #0a0c14;\n--surface: #151a28;\n--field: #1d2436;\n--text: #e8eefc;\n--muted: #8b95ab;\n--line: rgba(255,255,255,0.08);\n--accent: #55aaff;\n--accent-ink: #001726;\n}\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\nhtml, body { margin: 0; background: var(--bg); color: var(--text); }\nbody {\nfont: 16px/1.4 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, system-ui, sans-serif;\npadding: env(safe-area-inset-top) 16px calc(96px + env(safe-area-inset-bottom));\nmax-width: 520px; margin: 0 auto;\n}\nh1 { margin: 24px 0 4px; font-size: 24px; letter-spacing: -0.02em; }\n.sub { color: var(--muted); margin: 0 0 20px; font-size: 14px; }\nh2 {\nmargin: 22px 0 8px; font-size: 12px; font-weight: 600;\nletter-spacing: 0.08em; text-transform: uppercase; color: var(--muted);\n}\n.card {\nbackground: var(--surface); border: 1px solid var(--line); border-radius: 16px; overflow: hidden;\n}\n.row {\ndisplay: flex; align-items: center; justify-content: space-between; gap: 12px;\npadding: 14px 16px;\n}\n.row + .row { border-top: 1px solid var(--line); }\n.row-text { flex: 1; min-width: 0; }\n.row-text small { display: block; color: var(--muted); font-size: 13px; margin-top: 2px; }\nselect, input[type=\"color\"] {\nfont: inherit; color: var(--text); background: var(--field);\nborder: 1px solid var(--line); border-radius: 10px;\n}\nselect { padding: 8px 10px; max-width: 160px; }\ninput[type=\"color\"] {\nwidth: 44px; height: 34px; padding: 2px; cursor: pointer;\n}\n.switch { position: relative; flex: none; width: 50px; height: 30px; }\n.switch input { opacity: 0; width: 0; height: 0; position: absolute; }\n.switch span {\nposition: absolute; inset: 0; border-radius: 30px; background: var(--field);\nborder: 1px solid var(--line); transition: 0.2s;\n}\n.switch span::after {\ncontent: \"\"; position: absolute; width: 24px; height: 24px; border-radius: 50%;\ntop: 2px; left: 2px; background: #fff; transition: 0.2s;\n}\n.switch input:checked + span { background: var(--accent); border-color: var(--accent); }\n.switch input:checked + span::after { transform: translateX(20px); }\n.bar {\nposition: fixed; left: 0; right: 0; bottom: 0;\npadding: 12px 16px calc(12px + env(safe-area-inset-bottom));\nbackground: linear-gradient(transparent, var(--bg) 30%);\n}\n.save {\nwidth: 100%; max-width: 488px; margin: 0 auto; display: block;\npadding: 14px; border: 0; border-radius: 14px; font: inherit; font-weight: 700;\nbackground: var(--accent); color: var(--accent-ink); cursor: pointer;\n}\n.color-only.hidden { display: none; }\n</style>\n</head>\n<body>\n<h1>3DP LCD</h1>\n<p class=\"sub\">Nozzle = hour \u00b7 Bed = minute \u00b7 Progress = day</p>\n<h2>Time</h2>\n<div class=\"card\">\n<div class=\"row\">\n<div class=\"row-text\">Hour format</div>\n<select id=\"HourMode\">\n<option value=\"0\">System</option>\n<option value=\"1\">12-hour</option>\n<option value=\"2\">24-hour</option>\n</select>\n</div>\n</div>\n<h2>Display</h2>\n<div class=\"card\">\n<div class=\"row\">\n<div class=\"row-text\">Day progress bar</div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"ShowProgress\" checked><span></span></label>\n</div>\n<div class=\"row\">\n<div class=\"row-text\">XYZ line<small>Month / day / seconds</small></div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"ShowXYZ\" checked><span></span></label>\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Remaining + status</div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"ShowRemaining\" checked><span></span></label>\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Weekday .GCO</div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"ShowWeekday\" checked><span></span></label>\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Spinning fan</div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"FanSpin\" checked><span></span></label>\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Show F100%</div>\n<label class=\"switch\"><input type=\"checkbox\" id=\"ShowFeedrate\" checked><span></span></label>\n</div>\n</div>\n<div class=\"color-only\" id=\"colorSection\">\n<h2>Colors</h2>\n<div class=\"card\">\n<div class=\"row\">\n<div class=\"row-text\">Background</div>\n<input type=\"color\" id=\"BackgroundColor\" value=\"#000055\">\n</div>\n<div class=\"row\">\n<div class=\"row-text\">LCD panel</div>\n<input type=\"color\" id=\"PanelColor\" value=\"#0000aa\">\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Primary text</div>\n<input type=\"color\" id=\"TextColor\" value=\"#ffffff\">\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Labels / accents</div>\n<input type=\"color\" id=\"AccentColor\" value=\"#55aaff\">\n</div>\n<div class=\"row\">\n<div class=\"row-text\">Progress bar fill</div>\n<input type=\"color\" id=\"BarColor\" value=\"#ffffff\">\n</div>\n</div>\n</div>\n<div class=\"bar\">\n<button class=\"save\" id=\"save\" type=\"button\">Save</button>\n</div>\n<script>\nvar RETURN_TO = '__RETURN_TO__';\nvar state = __STATE__;\nfunction $(id) { return document.getElementById(id); }\nfunction hexToInt(hex) {\nreturn parseInt(String(hex).replace('#', ''), 16);\n}\nfunction intToHex(n) {\nvar h = (n >>> 0).toString(16);\nwhile (h.length < 6) h = '0' + h;\nreturn '#' + h.slice(-6);\n}\nfunction load() {\nif (!state) state = {};\nif (state.color === false) {\ndocument.getElementById('colorSection').classList.add('hidden');\n}\n$('HourMode').value = String(state.HourMode != null ? state.HourMode : 0);\n['ShowProgress','ShowXYZ','ShowRemaining','ShowWeekday','FanSpin','ShowFeedrate'].forEach(function (k) {\n$(k).checked = state[k] !== false;\n});\nif (state.BackgroundColor != null) $('BackgroundColor').value = intToHex(state.BackgroundColor);\nif (state.PanelColor != null) $('PanelColor').value = intToHex(state.PanelColor);\nif (state.TextColor != null) $('TextColor').value = intToHex(state.TextColor);\nif (state.AccentColor != null) $('AccentColor').value = intToHex(state.AccentColor);\nif (state.BarColor != null) $('BarColor').value = intToHex(state.BarColor);\n}\nfunction collect() {\nreturn {\nHourMode: parseInt($('HourMode').value, 10),\nShowProgress: $('ShowProgress').checked,\nShowXYZ: $('ShowXYZ').checked,\nShowRemaining: $('ShowRemaining').checked,\nShowWeekday: $('ShowWeekday').checked,\nFanSpin: $('FanSpin').checked,\nShowFeedrate: $('ShowFeedrate').checked,\nBackgroundColor: hexToInt($('BackgroundColor').value),\nPanelColor: hexToInt($('PanelColor').value),\nTextColor: hexToInt($('TextColor').value),\nAccentColor: hexToInt($('AccentColor').value),\nBarColor: hexToInt($('BarColor').value)\n};\n}\n$('save').onclick = function () {\nvar payload = encodeURIComponent(JSON.stringify(collect()));\nwindow.location.href = RETURN_TO + payload;\n};\nload();\n</script>\n</body>\n</html>";
